const v = H.plot2d({ xMin: -3.2, xMax: 3.2, yMin: -1.6, yMax: 1.6 });
v.grid(); v.axes();
const k = P.k; // inner-function parameter: g(x) = k*x
// outer F(u) = sin(u),  inner g(x) = k*x
// f(x) = sin(k*x)
// f'(x) = F'(g) * g'(x) = cos(k*x) * k
const inner = x => k * x;
const f = x => Math.sin(inner(x));
const df = x => Math.cos(inner(x)) * k;
v.fn(f, { color: H.colors.accent, width: 3 });
v.fn(df, { color: H.colors.accent2, width: 2.5, dash: [6, 5] });
const x0 = 2.8 * Math.sin(t * 0.5);
const u0 = inner(x0);
const y0 = f(x0);
const m = df(x0);
